import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_kernel_code = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

template <typename scalar_t>
__global__ void fused_gemm_postprocess_kernel(
    const scalar_t* gemm_out, scalar_t* output,
    int rows, int cols, int max_dim
) {
    if (max_dim == 1) {  // Reduce along features
        int row = blockIdx.x * blockDim.x + threadIdx.x;
        if (row >= rows) return;

        scalar_t max_val = gemm_out[row * cols];
        for(int c=1; c<cols; c++) {
            scalar_t val = gemm_out[row*cols + c];
            if(val > max_val) max_val = val;
        }

        scalar_t mean_val = max_val;  // mean of single element
        scalar_t res = max_val - mean_val;
        output[row] = 0.5f * res * (1.0f + tanhf(0.7978845608f * (res + 0.044715f * res * res * res)));
    } else {  // Reduce along batch
        int col = blockIdx.x * blockDim.x + threadIdx.x;
        if (col >= cols) return;

        scalar_t max_val = gemm_out[col];
        for(int r=1; r<rows; r++) {
            scalar_t val = gemm_out[r*cols + col];
            if(val > max_val) max_val = val;
        }

        scalar_t mean_val = max_val;
        scalar_t res = max_val - mean_val;
        output[col] = 0.5f * res * (1.0f + tanhf(0.7978845608f * (res + 0.044715f * res * res * res)));
    }
}

torch::Tensor fused_postprocess_cuda(torch::Tensor gemm_out, int max_dim) {
    auto sizes = gemm_out.sizes();
    int rows = sizes[0], cols = sizes[1];
    auto opts = gemm_out.options();

    torch::Tensor output;
    if(max_dim == 1) output = torch::empty({rows, 1}, opts);
    else output = torch::empty({1, cols}, opts);

    int threads = 256;
    int elements = max_dim == 1 ? rows : cols;
    int blocks = (elements + threads - 1) / threads;

    AT_DISPATCH_FLOATING_TYPES(gemm_out.scalar_type(), "fused_postprocess", ([&] {
        fused_gemm_postprocess_kernel<scalar_t><<<blocks, threads>>>(
            gemm_out.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            rows, cols, max_dim
        );
    }));

    return output;
}
"""

fused_kernel_cpp = "torch::Tensor fused_postprocess_cuda(torch::Tensor gemm_out, int max_dim);"

fused_op = load_inline(
    name='fused_postprocess',
    cpp_sources=fused_kernel_cpp,
    cuda_sources=fused_kernel_code,
    functions=['fused_postprocess_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, max_dim):
        super(ModelNew, self).__init__()
        self.gemm = nn.Linear(in_features, out_features)
        self.max_dim = max_dim

    def forward(self, x):
        x = self.gemm(x)
        x = fused_op.fused_postprocess_cuda(x, self.max_dim)
        return x
